//! The Edwards curve against its definitions, the affine addition law,
//! RFC 8032's test vectors, and key pairs generated by OpenSSL.

// The carry addition truncates to bytes on purpose.
#![allow(clippy::cast_possible_truncation)]

use std::{fs, path::Path};

use proptest::prelude::*;

use super::{affine::Affine, d, extended::Extended};
use crate::{ed25519, fields::Field25519};

fn f(v: u64) -> Field25519 {
    Field25519::from_u64(v)
}

/// The affine twisted Edwards law for $a = -1$ ([Bernstein, Birkner, Joye,][bbjlp]
/// Lange and Peters, *Twisted Edwards curves*, AFRICACRYPT 2008):
/// $x_3 = (x_1 y_2 + y_1 x_2) / (1 + d x_1 x_2 y_1 y_2)$,
/// $y_3 = (y_1 y_2 + x_1 x_2) / (1 - d x_1 x_2 y_1 y_2)$. It is complete, so
/// it covers doubling and the identity as well.
///
/// [bbjlp]: https://eprint.iacr.org/2008/013
fn reference_add(p: &Affine, q: &Affine) -> Affine {
    let (x1, y1) = p.coordinates();
    let (x2, y2) = q.coordinates();
    let t = d() * x1 * x2 * y1 * y2;
    let x3 = (x1 * y2 + y1 * x2) * (Field25519::ONE + t).invert();
    let y3 = (y1 * y2 + x1 * x2) * (Field25519::ONE - t).invert();
    let (r, on_curve) = Affine::from_coordinates(x3, y3);
    assert!(on_curve.to_bool_vartime(), "reference left the curve");
    r
}

/// $\ell$, little-endian.
fn order_le() -> Vec<u8> {
    let mut bytes = crate::fields::ScalarEd25519::ZERO.to_bytes_be();
    // l = 2^252 + 27742317777372353535851937790883648493 as big-endian hex.
    let hex =
        "1000000000000000000000000000000014def9dea2f79cd65812631a5cf5d3ed";
    for (i, byte) in bytes.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).unwrap();
    }
    bytes.reverse();
    bytes
}

#[test]
fn constants() {
    // d = -121665 / 121666, and B has y = 4/5, x even, and order l.
    assert_eq!(d(), -f(121_665) * f(121_666).invert());
    let b = Affine::base();
    assert_eq!(b.coordinates().1, f(4) * f(5).invert());
    assert_eq!(b.coordinates().0.to_bytes_be()[31] & 1, 0, "x even");
    assert!(b.is_on_curve().to_bool_vartime());
    assert!(!Affine::from_coordinates(f(1), f(1)).1.to_bool_vartime());
    let lb = Extended::base().mul_bytes_le(&order_le());
    assert_eq!(lb, Extended::identity(), "l B = O");
    // d is not a square (Euler's criterion), which makes the addition
    // complete: d^((p-1)/2) = -1.
    let mut exponent = [u64::MAX; 4];
    exponent[0] = 0xffff_ffff_ffff_fff6; // (p - 1) / 2 = 2^254 - 10
    exponent[3] = 0x3fff_ffff_ffff_ffff;
    assert_eq!(d().pow_vartime(&exponent), -Field25519::ONE);
}

#[test]
fn small_multiples() {
    let b = Affine::base();
    let mut acc = Extended::identity();
    let mut expected = Affine::identity();
    for k in 1..=16u8 {
        acc = acc.add(&Extended::base());
        expected = reference_add(&expected, &b);
        assert_eq!(Affine::from(acc), expected, "{k}B by addition");
        assert_eq!(
            Affine::from(Extended::base().mul_bytes_le(&[k])),
            expected,
            "{k}B by mul"
        );
        assert_eq!(
            Affine::from(acc.double()),
            reference_add(&expected, &expected),
            "2({k}B)"
        );
    }
    let o = Extended::identity();
    assert_eq!(o.add(&Extended::base()), Extended::base());
    assert_eq!(o.double(), o);
    let minus_b = Extended::from(b.neg());
    assert_eq!(Extended::base().add(&minus_b), o);
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(16))]

    /// Addition and doubling agree with the affine law on random points, and
    /// the scalar multiplication is additive.
    #[test]
    fn laws(a in prop::collection::vec(any::<u8>(), 32), b in prop::collection::vec(any::<u8>(), 32)) {
        let p = Extended::base().mul_bytes_le(&a);
        let q = Extended::base().mul_bytes_le(&b);
        let (ap, aq) = (Affine::from(p), Affine::from(q));
        prop_assert!(ap.is_on_curve().to_bool_vartime());
        prop_assert_eq!(Affine::from(p.add(&q)), reference_add(&ap, &aq));
        prop_assert_eq!(Affine::from(p.double()), reference_add(&ap, &ap));
        // (a + b) B = a B + b B, over the integers (little-endian, with carry).
        let mut sum = vec![0u8; 33];
        let mut carry = 0u16;
        for i in 0..32 {
            let s = u16::from(a[i]) + u16::from(b[i]) + carry;
            sum[i] = s as u8;
            carry = s >> 8;
        }
        sum[32] = carry as u8;
        prop_assert_eq!(Extended::base().mul_bytes_le(&sum), p.add(&q));
    }
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn seed(s: &str) -> [u8; 32] {
    hex(s).try_into().unwrap()
}

/// [RFC 8032, section 7.1][rfc8032-7.1], TEST 1 to 3: secret key to public key.
///
/// [rfc8032-7.1]: https://www.rfc-editor.org/rfc/rfc8032#section-7.1
#[test]
fn rfc8032_vectors() {
    let cases = [
        (
            "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
            "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
        ),
        (
            "4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb",
            "3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c",
        ),
        (
            "c5aa8df43f9f837bedb7442f31dcb7b166d38535076f094b85ce3a2e0b4458f7",
            "fc51cd8e6218a1a38da47ed00230f0580816ed13ba3303ac5deb911548908025",
        ),
    ];
    for (secret, public) in cases {
        assert_eq!(
            ed25519::public_key(&seed(secret)).to_vec(),
            hex(public),
            "{secret}"
        );
    }
}

/// Public keys of seeds generated by OpenSSL (`scripts/gen-ec-vectors.sh`).
#[test]
fn openssl_key_pairs() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/keys/keypairs.txt");
    let mut seen = 0;
    for line in fs::read_to_string(path).unwrap().lines() {
        if let ["ED25519", private, public] =
            line.split_whitespace().collect::<Vec<_>>()[..]
        {
            assert_eq!(
                ed25519::public_key(&seed(private)).to_vec(),
                hex(public),
                "{private}"
            );
            seen += 1;
        }
    }
    assert_eq!(seen, 4);
}

/// The secret scalar is clamped: a multiple of 8, below 2^255, at least 2^254.
#[test]
fn clamping() {
    for byte in [0u8, 0x55, 0xff] {
        let s = ed25519::secret_scalar(&[byte; 32]);
        assert_eq!(s[0] & 7, 0);
        assert_eq!(s[31] & 0x80, 0);
        assert_eq!(s[31] & 0x40, 0x40);
    }
}
